#include <stdio.h>
#include <math.h>
#include <stdlib.h>

#define MAXN 1005
#define EPS 1e-9

int N, K;
double x[MAXN], y[MAXN], c[MAXN];

int check(double T) {
    // For each circle i: center (x[i],y[i]), radius T/c[i]
    // Check if any point is covered by >= K circles
    // Candidate points: pairwise intersections + centers
    double r[MAXN];
    for (int i = 0; i < N; i++) r[i] = T / c[i];

    // Check each center
    for (int i = 0; i < N; i++) {
        int cnt = 0;
        for (int j = 0; j < N; j++) {
            double dx = x[i]-x[j], dy = y[i]-y[j];
            if (sqrt(dx*dx+dy*dy) <= r[j]+EPS) cnt++;
        }
        if (cnt >= K) return 1;
    }

    // Check pairwise intersections
    for (int i = 0; i < N; i++) {
        for (int j = i+1; j < N; j++) {
            double dx = x[j]-x[i], dy = y[j]-y[i];
            double d = sqrt(dx*dx+dy*dy);
            if (d > r[i]+r[j]+EPS) continue;
            if (d < fabs(r[i]-r[j])-EPS) continue;
            if (d < EPS) continue;
            double a = (r[i]*r[i]-r[j]*r[j]+d*d)/(2*d);
            double h2 = r[i]*r[i]-a*a;
            if (h2 < 0) h2 = 0;
            double h = sqrt(h2);
            double mx = x[i]+a*dx/d, my = y[i]+a*dy/d;
            double px = -dy/d*h, py = dx/d*h;
            double pts[2][2] = {{mx+px,my+py},{mx-px,my-py}};
            for (int p = 0; p < 2; p++) {
                int cnt = 0;
                for (int k = 0; k < N; k++) {
                    double ex=pts[p][0]-x[k], ey=pts[p][1]-y[k];
                    if (sqrt(ex*ex+ey*ey) <= r[k]+EPS) cnt++;
                }
                if (cnt >= K) return 1;
            }
        }
    }
    return 0;
}

