static int feasible(double t) {
    const double EPS = 1e-10;
    double vals[120];
    int m = 0;

    /* Candidate centers:
       - every meat position
       - intersection points of boundaries of circles
         ((X-xi)^2 + (Y-yi)^2 <= (t/ci)^2)
    */
    for (int i = 0; i < N; i++) {
        vals[m++] = p[i].x;
        vals[m++] = p[i].y; /* dummy to keep array size large enough; not used as pair */
    }

    /* Check all meat positions first */
    for (int i = 0; i < N; i++) {
        int cnt = 0;
        for (int j = 0; j < N; j++) {
            double dx = p[i].x - p[j].x;
            double dy = p[i].y - p[j].y;
            double dist = sqrt(dx * dx + dy * dy);
            if (p[j].c * dist <= t + 1e-9) cnt++;
        }
        if (cnt >= K) return 1;
    }

    for (int i = 0; i < N; i++) {
        for (int j = i + 1; j < N; j++) {
            double r1 = t / p[i].c;
            double r2 = t / p[j].c;
            double x1 = p[i].x, y1 = p[i].y;
            double x2 = p[j].x, y2 = p[j].y;
            double dx = x2 - x1, dy = y2 - y1;
            double d2 = dx * dx + dy * dy;
            double d = sqrt(d2);

            if (d > r1 + r2 + EPS) continue;
            if (d < fabs(r1 - r2) - EPS) continue;
            if (d < EPS) continue;

            double a = (r1 * r1 - r2 * r2 + d2) / (2.0 * d);
            double h2 = r1 * r1 - a * a;
            if (h2 < -EPS) continue;
            if (h2 < 0) h2 = 0;
            double h = sqrt(h2);

            double mx = x1 + a * dx / d;
            double my = y1 + a * dy / d;

            double rx = -dy * h / d;
            double ry = dx * h / d;

            double cx[2] = {mx + rx, mx - rx};
            double cy[2] = {my + ry, my - ry};

            for (int s = 0; s < 2; s++) {
                int cnt = 0;
                for (int k = 0; k < N; k++) {
                    double ddx = cx[s] - p[k].x;
                    double ddy = cy[s] - p[k].y;
                    double dist = sqrt(ddx * ddx + ddy * ddy);
                    if (p[k].c * dist <= t + 1e-8) cnt++;
                }
                if (cnt >= K) return 1;
            }
        }
    }
    return 0;
}

