public class Main {
    static class Meat {
        double x, y, c;
        Meat(double x, double y, double c) {
            this.x = x;
            this.y = y;
            this.c = c;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int K = sc.nextInt();
        Meat[] meats = new Meat[N];
        for (int i = 0; i < N; i++) {
            double x = sc.nextDouble();
            double y = sc.nextDouble();
            double c = sc.nextDouble();
            meats[i] = new Meat(x, y, c);
        }

        double low = 0, high = 1e9;
        for (int iter = 0; iter < 100; iter++) {
            double mid = (low + high) / 2;
            if (can(mid, meats, K)) {
                high = mid;
            } else {
                low = mid;
            }
        }
        System.out.printf("%.10f\n", high);
    }

    static boolean can(double T, Meat[] meats, int K) {
        int n = meats.length;
        List<double[]> circles = new ArrayList<>();
        for (Meat m : meats) {
            double r = T / m.c;
            circles.add(new double[]{m.x, m.y, r});
        }

        // Check all pairwise intersections and centers
        List<double[]> cand = new ArrayList<>();
        for (double[] c : circles) {
            cand.add(new double[]{c[0], c[1]});
        }
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                double x1 = circles.get(i)[0], y1 = circles.get(i)[1], r1 = circles.get(i)[2];
                double x2 = circles.get(j)[0], y2 = circles.get(j)[1], r2 = circles.get(j)[2];
                double dx = x2 - x1, dy = y2 - y1;
                double d2 = dx * dx + dy * dy;
                double d = Math.sqrt(d2);
                if (d > r1 + r2 + 1e-12 || d < Math.abs(r1 - r2) - 1e-12) continue;
                double a = (r1 * r1 - r2 * r2 + d2) / (2 * d);
                double h2 = r1 * r1 - a * a;
                if (h2 < 0) continue;
                double h = Math.sqrt(h2);
                double xm = x1 + a * dx / d;
                double ym = y1 + a * dy / d;
                cand.add(new double[]{xm + h * dy / d, ym - h * dx / d});
                cand.add(new double[]{xm - h * dy / d, ym + h * dx / d});
            }
        }
        for (double[] p : cand) {
            int cnt = 0;
            for (Meat m : meats) {
                double dist = Math.hypot(p[0] - m.x, p[1] - m.y);
                if (dist * m.c <= T + 1e-12) cnt++;
            }
            if (cnt >= K) return true;
        }
        return false;
    }
}

