public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }
    }

    static class Circle {
        double x, y, r;
        Circle(double x, double y, double r) {
            this.x = x;
            this.y = y;
            this.r = r;
        }
    }

    static final double EPS = 1e-10;

    static int N, K;
    static double[] x, y, c;

    static boolean contains(Circle cir, double px, double py) {
        double dx = px - cir.x;
        double dy = py - cir.y;
        return dx * dx + dy * dy <= cir.r * cir.r + 1e-9;
    }

    static List<double[]> intersections(Circle a, Circle b) {
        List<double[]> res = new ArrayList<>();

        double dx = b.x - a.x;
        double dy = b.y - a.y;
        double d2 = dx * dx + dy * dy;
        double d = Math.sqrt(d2);

        if (d < EPS) {
            return res;
        }

        if (d > a.r + b.r + 1e-9) return res;
        if (d < Math.abs(a.r - b.r) - 1e-9) return res;

        double aa = (a.r * a.r - b.r * b.r + d2) / (2.0 * d);
        double h2 = a.r * a.r - aa * aa;
        if (h2 < -1e-9) return res;
        if (h2 < 0) h2 = 0;
        double h = Math.sqrt(h2);

        double xm = a.x + aa * dx / d;
        double ym = a.y + aa * dy / d;

        double rx = -dy * h / d;
        double ry = dx * h / d;

        res.add(new double[]{xm + rx, ym + ry});
        if (h > 1e-12) {
            res.add(new double[]{xm - rx, ym - ry});
        }

        return res;
    }

    static boolean ok(double t) {
        Circle[] circles = new Circle[N];
        for (int i = 0; i < N; i++) {
            circles[i] = new Circle(x[i], y[i], t / c[i]);
        }

        // Candidate points:
        // 1. centers of circles
        for (int i = 0; i < N; i++) {
            int cnt = 0;
            for (int j = 0; j < N; j++) {
                if (contains(circles[j], circles[i].x, circles[i].y)) cnt++;
            }
            if (cnt >= K) return true;
        }

        // 2. pairwise intersection points of circle boundaries
        for (int i = 0; i < N; i++) {
            for (int j = i + 1; j < N; j++) {
                List<double[]> pts = intersections(circles[i], circles[j]);
                for (double[] p : pts) {
                    int cnt = 0;
                    for (int k = 0; k < N; k++) {
                        if (contains(circles[k], p[0], p[1])) cnt++;
                    }
                    if (cnt >= K) return true;
                }
            }
        }

        return false;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        N = fs.nextInt();
        K = fs.nextInt();

        x = new double[N];
        y = new double[N];
        c = new double[N];

        for (int i = 0; i < N; i++) {
            x[i] = fs.nextDouble();
            y[i] = fs.nextDouble();
            c[i] = fs.nextDouble();
        }

        double low = 0.0, high = 1.0;
        while (!ok(high)) high *= 2.0;

        for (int iter = 0; iter < 80; iter++) {
            double mid = (low + high) / 2.0;
            if (ok(mid)) high = mid;
            else low = mid;
        }

        System.out.printf("%.10f%n", high);
    }
}

