    }

    auto feasible = [&](ld T) -> bool {
        // collect candidate points
        vector<Point> cand;
        for (int i = 0; i < N; ++i) {
            cand.push_back(pts[i]); // circle center
        }
        // pairwise intersections
        for (int i = 0; i < N; ++i) {
            for (int j = i+1; j < N; ++j) {
                ld r1 = T / c[i];
                ld r2 = T / c[j];
                ld d = dist(pts[i], pts[j]);
                if (d > r1 + r2 + EPS || d < fabs(r1 - r2) - EPS) continue;
                // find intersection points
                ld a = (r1*r1 - r2*r2 + d*d) / (2*d);
                ld hsq = r1*r1 - a*a;
                if (hsq < 0) hsq = 0;
                ld h = sqrt(hsq);
                Point mid(pts[i].x + a*(pts[j].x - pts[i].x)/d,
                          pts[i].y + a*(pts[j].y - pts[i].y)/d);
                Point p1(mid.x + h*(pts[j].y - pts[i].y)/d,
