                Point p2(mid.x - h*(pts[j].y - pts[i].y)/d,
                         mid.y + h*(pts[j].x - pts[i].x)/d);
                cand.push_back(p1);
                if (d > 0) cand.push_back(p2);
            }
        }

        for (auto &p : cand) {
            int cnt = 0;
            for (int i = 0; i < N; ++i) {
                ld r = T / c[i];
                if (dist(p, pts[i]) <= r + EPS) cnt++;
            }
            if (cnt >= K) return true;
        }
        return false;
    };

    ld lo = 0, hi = 1e7;
    for (int iter = 0; iter < 60; ++iter) {
        ld mid = (lo + hi) / 2;
        if (feasible(mid)) hi = mid;
        else lo = mid;
