    vector<Point> p(N);
    for (int i = 0; i < N; ++i) {
        cin >> p[i].x >> p[i].y >> p[i].c;
    }

    auto can = [&](double T) -> bool {
        // For each meat i, feasible heat-source positions satisfy:
        // distance((X,Y), (xi,yi)) <= T / ci
        // i.e. inside circle i.
        // We need a point contained in at least K circles.

        vector<pair<double,double>> cand;
        cand.reserve(N + N * N * 2);

        for (int i = 0; i < N; ++i) {
            cand.push_back({p[i].x, p[i].y});
        }

        vector<double> r(N);
        for (int i = 0; i < N; ++i) r[i] = T / p[i].c;

        for (int i = 0; i < N; ++i) {
            for (int j = i + 1; j < N; ++j) {
                double x1 = p[i].x, y1 = p[i].y, r1 = r[i];
                double x2 = p[j].x, y2 = p[j].y, r2 = r[j];
                double dx = x2 - x1, dy = y2 - y1;
                double d2 = dx * dx + dy * dy;
                double d = sqrt(d2);

                if (d > r1 + r2 + EPS) continue;
                if (d < fabs(r1 - r2) - EPS) continue;
                if (d < EPS) continue; // same center; no unique intersection points

                double a = (r1 * r1 - r2 * r2 + d2) / (2.0 * d);
                double h2 = r1 * r1 - a * a;
                if (h2 < -EPS) continue;
                h2 = max(0.0, h2);
                double h = sqrt(h2);

                double mx = x1 + a * dx / d;
                double my = y1 + a * dy / d;

                double rx = -dy * h / d;
                double ry = dx * h / d;

                cand.push_back({mx + rx, my + ry});
                cand.push_back({mx - rx, my - ry});
            }
        }

        for (auto [X, Y] : cand) {
            int cnt = 0;
            for (int i = 0; i < N; ++i) {
                double dx = X - p[i].x;
                double dy = Y - p[i].y;
                if (dx * dx + dy * dy <= r[i] * r[i] + 1e-8) {
                    ++cnt;
                }
            }
            if (cnt >= K) return true;
        }

        return false;
    };

    double lo = 0.0, hi = 1.0;
    while (!can(hi)) hi *= 2.0;

    for (int it = 0; it < 80; ++it) {
        double mid = (lo + hi) / 2.0;
        if (can(mid)) hi = mid;
        else lo = mid;
    }

    cout << fixed << setprecision(15) << hi << '\n';
    return 0;
}

