        mx = x1 + a*dx/d
        my = y1 + a*dy/d
        if h < 1e-12:
            return [(mx, my)]
        px, py = -dy/d * h, dx/d * h
        return [(mx+px, my+py), (mx-px, my-py)]

    def feasible(T):
        radii = [T / c for (x, y, c) in meats]
        candidates = []
        for i, (x, y, c) in enumerate(meats):
            candidates.append((x, y))  # center of each circle
        for i in range(N):
            for j in range(i+1, N):
                x1,y1,_ = meats[i]; x2,y2,_ = meats[j]
                pts = circle_intersections(x1,y1,radii[i],x2,y2,radii[j])
                candidates.extend(pts)
        for (px, py) in candidates:
            count = 0
            for i, (xi, yi, ci) in enumerate(meats):
                dist = math.sqrt((px-xi)**2+(py-yi)**2)
                if ci * dist <= T + 1e-9:
                    count += 1
            if count >= K:
                return True
        return False

    lo, hi = 0.0, 1e18
    for _ in range(100):
        mid = (lo + hi) / 2
        if feasible(mid):
            hi = mid
        else:
            lo = mid
    print(f"{hi:.10f}")

